<?php require __DIR__.'/../includes/bootstrap.php';if(is_admin()){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT * FROM admins WHERE username=?');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['username'];header('Location: index.php');exit;}$error='اسم المستخدم أو كلمة المرور غير صحيحة.';}$page_title='دخول الإدارة';require __DIR__.'/../includes/header.php';?><main class="container" style="max-width:480px"><div class="panel"><h1 class="gold">دخول لوحة التحكم</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>اسم المستخدم</label><input name="username" required autocomplete="username"></div><div class="field"><label>كلمة المرور</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn">دخول</button></form></div></main><?php require __DIR__.'/../includes/footer.php';?>
